options.afterRender:
const currentUrl = window.location.href;

// ?orgId önceki kısım
const urlBeforeOrgId = currentUrl.split('?orgId')[0];

// "/" karakterinden sonrasını al
const pathAfterSlash = urlBeforeOrgId.substring(urlBeforeOrgId.lastIndexOf('/') + 1);

// "-" ile ayır
const pathParts = pathAfterSlash.split('-');

// Başlığı oluştur (tüm parçaları capitalize et ve birleştir)
const formattedTitle = pathParts
  .map(word => word.charAt(0).toUpperCase() + word.slice(1))
  .join(' ');

// HTML'deki başlık 
const titleElement = document.getElementById('title');

if (titleElement) {
  titleElement.textContent = formattedTitle;
}

