{% if '${direction:csv}' == 'ingress' %}
WITH policy_base AS (
    -- template_version tablosundan qos_download kolonunu alıp site dizisini açıyoruz 
   SELECT
        t.id AS template_id,
        site_element
    FROM tenant.public.site s
    INNER JOIN tenant.public.template_version t ON s.template_version_id = t.id
    CROSS JOIN UNNEST(
        CAST(json_extract(qos_download, '$.site') AS ARRAY(JSON))
    ) AS u(site_element)
    WHERE CAST(s.id AS VARCHAR) = '${sites:csv}'
),
interface_base AS (
    -- site -> site -> interface hiyerarşisini takip ediyoruz
    SELECT
        template_id,
        iface
    FROM policy_base
    CROSS JOIN UNNEST(
        CAST(json_extract(site_element, '$.site.interface') AS ARRAY(JSON))
    ) AS t(iface)
),
extracted_classes AS (
    -- interface -> interface -> _class dizisini açıp metrikleri topluyoruz
    SELECT
          template_id,
          json_extract_scalar(iface, '$.name')                                              AS interface_name,
          json_extract_scalar(iface, '$.policyName')                                        AS policy_name,
          json_extract_scalar(cls_element, '$.name')                                        AS class_name,

          -- Veriler bazen bir alt _class objesinde, bazen direkt root'ta
          CAST(
              COALESCE(
                  json_extract_scalar(cls_element, '$._class.priority'),
                  json_extract_scalar(cls_element, '$.priority')
              ) AS INTEGER
          )                                                                                  AS priority,

          COALESCE(
              json_extract_scalar(cls_element, '$._class.bandwidth'),
              json_extract_scalar(cls_element, '$.bandwidth')
          )                                                                                  AS bandwidth,

          COALESCE(
              json_extract_scalar(cls_element, '$._class.ceiling'),
              json_extract_scalar(cls_element, '$.ceiling')
          )                                                                                  AS ceiling,

          COALESCE(
              json_extract_scalar(cls_element, '$._class.burst'),
              json_extract_scalar(cls_element, '$.burst')
          )                                                                                  AS burst,

          -- JSON'daki isDefault alanını yakala, yoksa false dön
          COALESCE(
              TRY_CAST(json_extract_scalar(cls_element, '$._class.isDefault') AS BOOLEAN),
              TRY_CAST(json_extract_scalar(cls_element, '$.isDefault')        AS BOOLEAN),
              FALSE
          )                                                                                  AS is_default,

          -- Description ID'sini her iki seviyede de ara
          TRY_CAST(
              COALESCE(
                  json_extract_scalar(cls_element, '$._class.allFields.description.id'),
                  json_extract_scalar(cls_element, '$.allFields.description.id')
              ) AS UUID
          )                                                                                  AS desc_id

      FROM interface_base
      CROSS JOIN UNNEST(
          CAST(json_extract(iface, '$.interface._class') AS ARRAY(JSON))
      ) AS t(cls_element)
),
classes_from_db AS (
-- Final: temp_obj tablosundan obj_name (açıklama) bilgisini getiriyoruz
SELECT 
    ec.interface_name,
    ec.policy_name,
    ec.class_name,
    ec.is_default,
    ec.priority,
    ec.bandwidth,
    ec.ceiling,
    ec.burst,
    t.obj_name 
FROM extracted_classes ec
LEFT JOIN tenant.public.temp_obj t ON ec.desc_id = t.id
ORDER BY ec.interface_name, ec.is_default DESC, ec.priority
),

 {% elseif '${direction}' == 'egress'%}
 WITH policy_base AS (
    SELECT
        t.id AS template_id,
        shaper_element
    FROM tenant.public.site s
    inner join tenant.public.template_version t on s.template_version_id = t.id 
    CROSS JOIN UNNEST(
        CAST(json_extract(traffic_policy, '$.shaper') AS ARRAY(JSON))
    ) AS t(shaper_element)
    WHERE  cast(s.id as varchar) = '${sites:csv}'
),
extracted_metrics AS (
    -- 1. Default sınıf verileri (is_default = true)
    SELECT
        template_id,
        json_extract_scalar(shaper_element, '$.name')                                  AS shaper_name,
        'default'                                                                        AS class_name,
        CAST(json_extract_scalar(shaper_element, '$.shaper.default.priority') AS INTEGER) AS priority,
        json_extract_scalar(shaper_element, '$.shaper.default.bandwidth')               AS bandwidth,
        json_extract_scalar(shaper_element, '$.shaper.default.ceiling')                 AS ceiling,
        json_extract_scalar(shaper_element, '$.shaper.default.burst')                   AS burst,
        TRY_CAST(
            json_extract_scalar(shaper_element, '$.shaper.allFields.description.id')
            AS UUID
        )                                                                                AS desc_id,
        TRUE                                                                             AS is_default
    FROM policy_base

    UNION ALL

    -- 2. Alt sınıflar (_class dizisi) (is_default = false)
    SELECT
        pb.template_id,
        json_extract_scalar(pb.shaper_element, '$.name')                                AS shaper_name,
        json_extract_scalar(sub_element, '$.name')                                      AS class_name,
        CAST(json_extract_scalar(sub_element, '$._class.priority') AS INTEGER)          AS priority,
        json_extract_scalar(sub_element, '$._class.bandwidth')                          AS bandwidth,
        json_extract_scalar(sub_element, '$._class.ceiling')                            AS ceiling,
        NULL                                                                             AS burst,
        TRY_CAST(
            json_extract_scalar(sub_element, '$._class.allFields.description.id')
            AS UUID
        )                                                                                AS desc_id,
        FALSE                                                                            AS is_default
    FROM policy_base pb
    CROSS JOIN UNNEST(
        CAST(json_extract(pb.shaper_element, '$.shaper._class') AS ARRAY(JSON))
    ) AS t(sub_element)
),
classes_from_db AS (
    SELECT
        em.shaper_name,
        em.class_name,
        em.is_default,
        em.priority,
        em.bandwidth,
        em.ceiling,
        em.burst,
        t.obj_name 
    FROM extracted_metrics em
    LEFT JOIN tenant.public.temp_obj t ON em.desc_id = t.id
    ORDER BY shaper_name, is_default DESC, priority
),

    {% endif %}
  classes_from_metrics as (
    select classes
  from(
          select
              "2/key"   as host ,
              "7/key"   as classes
          from quickwit.metrics3."
                    //ttl=150
                    //refresh=75
                    //cache=false
                    //name=Dataplane Status
                    //columns=7/key,2/key
                    //dbtype=qw
                    //qwindex=metrics3
                    //historyenabled=${enable_history}
                    //historyindex=metrics3_15
                    //replacefromcolumns=/3/buckets/2/buckets/7/buckets/
                    //hasjs=true
                    //from=${__from:date:seconds}
                    //to=${__to:date:seconds}
                  {
    ""aggs"": {
      ""3"": {
        ""aggs"": {
          ""2"": {
            ""aggs"": {
              ""7"": {
                ""terms"": {
                  ""field"": ""span_attributes.m_name"",
                  ""size"": 9999,
                  ""missing"": ""N/A"",
                  ""order"": {
                    ""_key"": ""desc""
                  },
                  ""min_doc_count"": 1
                }
              }
            },
            ""terms"": {
              ""field"": ""{% if '${direction:csv}' == 'ingress' %}span_attributes.m_site_id{% elseif '${direction}' == 'egress'%}span_attributes.h{% endif %}"",
              ""size"": 9999,
              ""missing"": ""N/A"",
              ""order"": {
                ""_key"": ""desc""
              },
              ""min_doc_count"": 1
            }
          }
        },
        ""date_histogram"": {
          ""field"": ""span_start_timestamp_nanos"",
          ""fixed_interval"": ""${retention_period_in_hours}h"",
          ""min_doc_count"": 1
        }
      }
    },
    ""query"": ""span_attributes.p:netlink 
        AND {% if '${direction:csv}' == 'ingress' %} span_attributes.m_site_id:IN [${sites:pipe}] 
                              {% elseif '${direction:csv}' == 'egress' %}NOT span_attributes.m_site_id:*  AND span_attributes.h:IN [${sites:pipe}]
                              {% endif %}"",

    ""max_hits"": 0,
    ""start_timestamp"": ""${__from:date:seconds}"",
    ""end_timestamp"": ""${__to:date:seconds}""
  }    " as i where "2/key" is not null
  )as q
  ),
  default_finder as (
      (select obj_name from classes_from_db where is_default)
  )


select  from_unixtime(cast(max_time/1000000000 AS double)) AS max_time,
        from_unixtime(cast(min_time/1000000000 AS double)) AS min_time,
        from_unixtime(cast(max_time / 1000000000 as double))  AS m,  
         case when q.clazz in (select obj_name from classes_from_db) then   q.clazz else (select * from default_finder) end   Class , 
        sum(q.max_tx - q.min_tx ) / ( case when (max_time - min_time) / 1000000000 = 0 then ${resolution_in_seconds:csv} 
                                         else (max_time  -min_time)/1000000000   end )  as PACKETS
from(
        select 
            "2221/2/key"  as clazz,
            cast("222/value"  as double)     as min_tx,
            cast("2221/value" as double)     as max_tx, 
            cast("11/value"  as double)    as min_time,
            cast("111/value"  as double)   as max_time,
            *
        from quickwit.metrics3."
                  //ttl=150
                  //refresh=75
                  //cache=false
                  //name=Dataplane Status
                  //columns=2221/2/key,222/value,2221/value,11/value,111/value
                  //dbtype=qw
                  //qwindex=metrics3
                  //historyenabled=${enable_history}
                  //historyindex=metrics3_15
                  //replacefromcolumns=/3/buckets/2/buckets/
                  //hasjs=true
                  //from=${__from:date:seconds}
                  //to=${__to:date:seconds}

                  {
                    ""aggs"": {
                      ""3"": {
                        ""aggs"": {
                          ""2"": {
                            ""aggs"": {
                              ""11"": {
                                ""min"": {
                                  ""field"": ""span_start_timestamp_nanos""
                                }
                              },
                              ""111"": {
                                ""max"": {
                                  ""field"": ""span_start_timestamp_nanos""
                                }
                              },
                              ""222"": {
                                ""min"": {
                                  ""field"": ""span_attributes.value""
                                }
                              },
                              ""2221"": {
                                ""max"": {
                                  ""field"": ""span_attributes.value""
                                }
                              }
                            },
                            ""terms"": {
                              ""field"": ""span_attributes.m_name"",
                              ""size"": 9999,
                              ""missing"": ""N/A"",
                              ""order"": {
                                ""_key"": ""desc""
                              },
                              ""min_doc_count"": 1
                            }
                          }
                        },
                        ""date_histogram"": {
                          ""field"": ""span_start_timestamp_nanos"",
                          ""fixed_interval"": ""${resolution_in_seconds:csv}s"",
                          ""min_doc_count"": 1
                        }
                      }
                    },
                       ""query"": ""span_attributes.p:netlink 
                        AND span_attributes.t:IN [ipt_packets] 
                        AND span_attributes.ti:class-htb*
                        AND span_attributes.m_name:IN [${class_names:pipe}] 
                        AND span_attributes.pi:IN [${interfaces_trino:pipe}]
                        AND {% if '${direction:csv}' == 'ingress' %}  span_attributes.m_site_id:IN [${sites:pipe}] AND span_attributes.m_name:IN [${class_names:pipe}] 
                            {% elseif '${direction:csv}' == 'egress' %} NOT span_attributes.m_site_id:* AND  span_attributes.h:IN [${sites:pipe}] AND span_attributes.m_name:IN [${class_names:pipe}]  {% endif %}"",
                    ""max_hits"": 0, 
                    ""start_timestamp"": ""${__from:date:seconds}"",
                    ""end_timestamp"": ""${__to:date:seconds}""
} " as i

 where "2221/2/key" is not null 
)as q 
group by q.clazz, max_time, min_time
order by max_time, q.clazz

