extracted_classes AS (
    -- interface -> interface -> _class dizisini açıp metrikleri topluyoruz
    SELECT
          template_id,
          json_extract_scalar(iface, '$.name')                                              AS interface_name,
          json_extract_scalar(iface, '$.policyName')                                        AS policy_name,
          json_extract_scalar(cls_element, '$.name')                                        AS class_name,

          -- Veriler bazen bir alt _class objesinde, bazen direkt root'ta
          CAST(
              COALESCE(
                  json_extract_scalar(cls_element, '$._class.priority'),
                  json_extract_scalar(cls_element, '$.priority')
              ) AS INTEGER
          )                                                                                  AS priority,

          COALESCE(
              json_extract_scalar(cls_element, '$._class.bandwidth'),
              json_extract_scalar(cls_element, '$.bandwidth')
          )                                                                                  AS bandwidth,

          COALESCE(
              json_extract_scalar(cls_element, '$._class.ceiling'),
              json_extract_scalar(cls_element, '$.ceiling')
          )                                                                                  AS ceiling,

          COALESCE(
              json_extract_scalar(cls_element, '$._class.burst'),
              json_extract_scalar(cls_element, '$.burst')
          )                                                                                  AS burst,

          -- JSON'daki isDefault alanını yakala, yoksa false dön
          COALESCE(
              TRY_CAST(json_extract_scalar(cls_element, '$._class.isDefault') AS BOOLEAN),
              TRY_CAST(json_extract_scalar(cls_element, '$.isDefault')        AS BOOLEAN),
              FALSE
          )                                                                                  AS is_default,

          -- Description ID'sini her iki seviyede de ara
          TRY_CAST(
              COALESCE(
                  json_extract_scalar(cls_element, '$._class.allFields.description.id'),
                  json_extract_scalar(cls_element, '$.allFields.description.id')
              ) AS UUID
          )                                                                                  AS desc_id

      FROM interface_base
      CROSS JOIN UNNEST(
          CAST(json_extract(iface, '$.interface._class') AS ARRAY(JSON))
      ) AS t(cls_element)
),
